import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import axios from 'axios';
import { toast } from 'react-toastify';

// ─── Quiz Component shown between lessons ───────────────────────────────────
function QuizPanel({ quiz, onPass, onSkip }) {
  const [answers, setAnswers] = useState({});
  const [result, setResult] = useState(null);
  const [submitting, setSubmitting] = useState(false);

  const handleSubmit = async () => {
    if (Object.keys(answers).length < quiz.questions.length) {
      toast.error('Answer all questions before submitting');
      return;
    }
    setSubmitting(true);
    try {
      const payload = quiz.questions.map((_, i) => answers[i] ?? -1);
      const { data } = await axios.post(`/api/quizzes/${quiz._id}/attempt`, { answers: payload });
      setResult(data);
      if (data.passed) {
        toast.success(`Quiz passed! +20 XP`);
        setTimeout(() => onPass(), 1800);
      }
    } catch { toast.error('Submission failed'); }
    setSubmitting(false);
  };

  const reset = () => { setAnswers({}); setResult(null); };

  return (
    <div style={{
      background: '#111113', border: '1px solid rgba(255,255,255,0.08)',
      borderRadius: '16px', padding: '28px', marginTop: '24px',
    }}>
      {/* Header */}
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '24px' }}>
        <div>
          <div style={{ fontSize: '11px', fontWeight: 600, color: '#8b5cf6', letterSpacing: '0.08em', textTransform: 'uppercase', marginBottom: '6px' }}>
            Knowledge Check
          </div>
          <h3 style={{ fontSize: '18px', fontWeight: 700, letterSpacing: '-0.01em' }}>{quiz.title}</h3>
        </div>
        <div style={{ display: 'flex', gap: '8px' }}>
          <span className="badge badge-neutral">Pass: {quiz.passingScore}%</span>
          <span className="badge badge-neutral">{quiz.questions.length} questions</span>
        </div>
      </div>

      {/* Questions */}
      {!result ? (
        <>
          {quiz.questions.map((q, qi) => (
            <div key={qi} style={{ marginBottom: '28px' }}>
              <div style={{ fontSize: '14px', fontWeight: 600, color: '#fafafa', marginBottom: '14px', lineHeight: 1.5 }}>
                <span style={{ color: '#52525b', marginRight: '8px', fontFamily: 'monospace' }}>{qi + 1}.</span>
                {q.question}
              </div>
              <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
                {q.options.map((opt, oi) => {
                  const selected = answers[qi] === oi;
                  return (
                    <button key={oi} onClick={() => setAnswers(a => ({ ...a, [qi]: oi }))} style={{
                      padding: '12px 16px', borderRadius: '10px', textAlign: 'left',
                      border: `1px solid ${selected ? '#8b5cf6' : 'rgba(255,255,255,0.06)'}`,
                      background: selected ? 'rgba(139,92,246,0.12)' : '#18181b',
                      color: selected ? '#c4b5fd' : '#a1a1aa',
                      cursor: 'pointer', fontSize: '14px', fontWeight: selected ? 500 : 400,
                      transition: 'all 0.15s',
                    }}
                      onMouseEnter={e => { if (!selected) e.currentTarget.style.borderColor = 'rgba(255,255,255,0.12)'; }}
                      onMouseLeave={e => { if (!selected) e.currentTarget.style.borderColor = 'rgba(255,255,255,0.06)'; }}
                    >
                      <span style={{ marginRight: '10px', color: '#3f3f46', fontFamily: 'monospace', fontSize: '12px' }}>
                        {String.fromCharCode(65 + oi)}.
                      </span>
                      {opt}
                    </button>
                  );
                })}
              </div>
            </div>
          ))}

          <div style={{ display: 'flex', gap: '10px', paddingTop: '8px', borderTop: '1px solid rgba(255,255,255,0.06)' }}>
            <button className="btn btn-accent" onClick={handleSubmit} disabled={submitting || Object.keys(answers).length < quiz.questions.length}
              style={{ opacity: Object.keys(answers).length < quiz.questions.length ? 0.5 : 1 }}>
              {submitting ? 'Checking...' : 'Submit answers'}
            </button>
            <button className="btn btn-ghost btn-sm" onClick={onSkip}>Skip for now</button>
          </div>
        </>
      ) : (
        /* Results */
        <div>
          {/* Score card */}
          <div style={{
            textAlign: 'center', padding: '32px',
            background: result.passed ? 'rgba(16,185,129,0.06)' : 'rgba(244,63,94,0.06)',
            border: `1px solid ${result.passed ? 'rgba(16,185,129,0.2)' : 'rgba(244,63,94,0.2)'}`,
            borderRadius: '12px', marginBottom: '24px',
          }}>
            <div style={{ fontSize: '48px', fontWeight: 900, color: result.passed ? '#10b981' : '#f43f5e', letterSpacing: '-0.03em', marginBottom: '6px' }}>
              {result.score}%
            </div>
            <div style={{ fontSize: '15px', fontWeight: 600, color: result.passed ? '#34d399' : '#fb7185', marginBottom: '4px' }}>
              {result.passed ? 'Passed' : 'Not quite'}
            </div>
            <div style={{ fontSize: '13px', color: '#71717a' }}>
              {result.correct} of {result.total} correct &nbsp;&middot;&nbsp; Need {quiz.passingScore}% to pass
            </div>
            {result.passed && (
              <div className="badge badge-green" style={{ marginTop: '12px', display: 'inline-flex' }}>+20 XP awarded</div>
            )}
          </div>

          {/* Per-question breakdown */}
          <div style={{ marginBottom: '20px' }}>
            <div style={{ fontSize: '12px', fontWeight: 600, color: '#52525b', textTransform: 'uppercase', letterSpacing: '0.06em', marginBottom: '12px' }}>
              Question breakdown
            </div>
            {result.results.map((r, i) => (
              <div key={i} style={{
                padding: '14px 16px', borderRadius: '10px', marginBottom: '8px',
                background: r.isCorrect ? 'rgba(16,185,129,0.06)' : 'rgba(244,63,94,0.06)',
                border: `1px solid ${r.isCorrect ? 'rgba(16,185,129,0.15)' : 'rgba(244,63,94,0.15)'}`,
              }}>
                <div style={{ display: 'flex', alignItems: 'flex-start', gap: '10px', marginBottom: r.explanation ? '8px' : 0 }}>
                  <span style={{ fontSize: '12px', color: r.isCorrect ? '#10b981' : '#f43f5e', fontWeight: 700, flexShrink: 0 }}>
                    {r.isCorrect ? 'Correct' : 'Wrong'}
                  </span>
                  <span style={{ fontSize: '13px', color: '#a1a1aa', lineHeight: 1.5 }}>{r.question}</span>
                </div>
                {r.explanation && (
                  <div style={{ fontSize: '12px', color: '#71717a', lineHeight: 1.5, paddingLeft: '52px', borderTop: '1px solid rgba(255,255,255,0.04)', paddingTop: '8px', marginTop: '4px' }}>
                    {r.explanation}
                  </div>
                )}
              </div>
            ))}
          </div>

          <div style={{ display: 'flex', gap: '10px' }}>
            {result.passed ? (
              <button className="btn btn-accent" onClick={onPass}>Continue to next lesson</button>
            ) : (
              <button className="btn btn-ghost" onClick={reset}>Try again</button>
            )}
            <button className="btn btn-ghost btn-sm" onClick={onSkip}>Skip quiz</button>
          </div>
        </div>
      )}
    </div>
  );
}

// ─── Certificate Banner ──────────────────────────────────────────────────────
function CertificateBanner({ courseId, courseName }) {
  const [cert, setCert] = useState(null);
  const [loading, setLoading] = useState(false);
  const [checked, setChecked] = useState(false);

  useEffect(() => {
    // Check if cert already exists
    axios.get('/api/certificates/my').then(r => {
      const existing = r.data.find(c => c.course?._id === courseId || c.course === courseId);
      if (existing) setCert(existing);
    }).catch(() => {}).finally(() => setChecked(true));
  }, [courseId]);

  const generate = async () => {
    setLoading(true);
    try {
      const { data } = await axios.post(`/api/certificates/generate/${courseId}`);
      setCert(data);
      toast.success('Certificate generated! +100 XP');
    } catch (err) {
      toast.error(err.response?.data?.message || 'Could not generate certificate');
    }
    setLoading(false);
  };

  if (!checked) return null;

  return (
    <div style={{
      background: cert ? 'rgba(251,191,36,0.05)' : 'rgba(139,92,246,0.06)',
      border: `1px solid ${cert ? 'rgba(251,191,36,0.2)' : 'rgba(139,92,246,0.15)'}`,
      borderRadius: '16px', padding: '28px', marginTop: '24px',
    }}>
      <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: '20px', flexWrap: 'wrap' }}>
        <div>
          <div style={{ fontSize: '11px', fontWeight: 600, color: cert ? '#fbbf24' : '#8b5cf6', letterSpacing: '0.08em', textTransform: 'uppercase', marginBottom: '8px' }}>
            {cert ? 'Certificate ready' : 'Course complete'}
          </div>
          <h3 style={{ fontSize: '18px', fontWeight: 700, marginBottom: '6px', letterSpacing: '-0.01em' }}>
            {cert ? `${courseName} — Certificate` : 'You completed this course'}
          </h3>
          {cert ? (
            <div style={{ fontSize: '13px', color: '#71717a' }}>
              ID: <span style={{ fontFamily: 'monospace', color: '#a1a1aa' }}>{cert.certificateId}</span>
              &nbsp;&middot;&nbsp; Issued {new Date(cert.issuedAt).toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' })}
            </div>
          ) : (
            <p style={{ fontSize: '14px', color: '#71717a', lineHeight: 1.6 }}>
              Generate your verified certificate now. It will be available to download as a PDF.
            </p>
          )}
        </div>
        <div style={{ display: 'flex', gap: '10px', flexShrink: 0 }}>
          {cert ? (
            <>
              <a
                href={`http://localhost:5000/api/certificates/download/${cert.certificateId}`}
                className="btn btn-primary"
                download
              >
                Download PDF
              </a>
              <Link to="/certificates" className="btn btn-ghost btn-sm">View all</Link>
            </>
          ) : (
            <button className="btn btn-accent" onClick={generate} disabled={loading}>
              {loading ? 'Generating...' : 'Generate certificate'}
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

// ─── Main Course Player ──────────────────────────────────────────────────────
export default function CoursePlayerPage() {
  const { courseId } = useParams();
  const navigate = useNavigate();
  const [course, setCourse] = useState(null);
  const [progressMap, setProgressMap] = useState({});
  const [completionPct, setCompletionPct] = useState(0);
  const [isCompleted, setIsCompleted] = useState(false);
  const [activeLesson, setActiveLesson] = useState(null);
  const [activeModule, setActiveModule] = useState(null);
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [quiz, setQuiz] = useState(null);
  const [quizLoading, setQuizLoading] = useState(false);
  const [showQuiz, setShowQuiz] = useState(false);
  const [markingDone, setMarkingDone] = useState(false);
  const [openModules, setOpenModules] = useState({});
  const videoRef = useRef(null);

  const loadProgress = useCallback(async () => {
    try {
      const { data } = await axios.get(`/api/progress/course/${courseId}`);
      const map = {};
      (data.progress || []).forEach(p => { map[p.lesson?.toString()] = p; });
      setProgressMap(map);
      setCompletionPct(data.completionPercentage || 0);
      setIsCompleted(data.isCompleted || false);
    } catch {}
  }, [courseId]);

  useEffect(() => {
    const load = async () => {
      try {
        const { data } = await axios.get(`/api/courses/${courseId}`);
        setCourse(data);
        // Open first module
        if (data.modules?.length) {
          setOpenModules({ [data.modules[0]._id]: true });
          const firstLesson = data.modules[0].lessons[0];
          if (firstLesson) {
            setActiveLesson(firstLesson);
            setActiveModule(data.modules[0]);
          }
        }
      } catch { navigate('/dashboard'); }
    };
    load();
    loadProgress();
  }, [courseId, navigate, loadProgress]);

  const isDone = (lessonId) => !!progressMap[lessonId?.toString()];

  const selectLesson = async (mod, lesson) => {
    setActiveModule(mod);
    setActiveLesson(lesson);
    setShowQuiz(false);
    setQuiz(null);
    // Load quiz for this lesson
    setQuizLoading(true);
    try {
      const { data } = await axios.get(`/api/quizzes/lesson/${lesson._id}`);
      setQuiz(data);
    } catch {}
    setQuizLoading(false);
  };

  const markComplete = async () => {
    if (!activeLesson || !activeModule) return;
    if (isDone(activeLesson._id)) {
      // If there's a quiz and it's not shown yet, show it
      if (quiz && !showQuiz) { setShowQuiz(true); return; }
      toast.info('Lesson already completed');
      return;
    }
    setMarkingDone(true);
    try {
      const { data } = await axios.post('/api/progress/lesson', {
        courseId,
        moduleId: activeModule._id,
        lessonId: activeLesson._id,
        watchedSeconds: videoRef.current?.currentTime || 60,
      });
      setCompletionPct(data.completionPercentage);
      setIsCompleted(data.isCompleted);
      setProgressMap(prev => ({ ...prev, [activeLesson._id.toString()]: { isCompleted: true } }));
      toast.success(`Lesson complete! +${data.xpAwarded} XP`);
      // Show quiz after marking done (if one exists)
      if (quiz) setShowQuiz(true);
    } catch { toast.error('Could not mark lesson as complete'); }
    setMarkingDone(false);
  };

  const goNextLesson = () => {
    if (!course || !activeModule || !activeLesson) return;
    const modIdx = course.modules.findIndex(m => m._id === activeModule._id);
    const lesIdx = activeModule.lessons.findIndex(l => l._id === activeLesson._id);
    if (lesIdx < activeModule.lessons.length - 1) {
      selectLesson(activeModule, activeModule.lessons[lesIdx + 1]);
    } else if (modIdx < course.modules.length - 1) {
      const nextMod = course.modules[modIdx + 1];
      setOpenModules(prev => ({ ...prev, [nextMod._id]: true }));
      selectLesson(nextMod, nextMod.lessons[0]);
    }
    setShowQuiz(false);
  };

  const toggleModule = (id) => setOpenModules(prev => ({ ...prev, [id]: !prev[id] }));

  const completedCount = Object.keys(progressMap).length;
  const totalLessons = course?.modules?.reduce((a, m) => a + m.lessons.length, 0) || 0;

  if (!course) return (
    <div className="loading-screen"><div className="spinner" /></div>
  );

  return (
    <div style={{ height: '100vh', display: 'flex', flexDirection: 'column', paddingTop: '60px', background: '#0a0a0b' }}>

      {/* Top bar */}
      <div style={{
        height: '52px', background: 'rgba(10,10,11,0.95)',
        borderBottom: '1px solid rgba(255,255,255,0.06)',
        display: 'flex', alignItems: 'center', padding: '0 20px', gap: '16px', flexShrink: 0,
      }}>
        <button onClick={() => navigate('/dashboard')} style={{
          background: 'none', border: 'none', color: '#71717a', cursor: 'pointer',
          fontSize: '13px', display: 'flex', alignItems: 'center', gap: '6px',
          padding: '4px 8px', borderRadius: '6px', transition: 'color 0.15s',
        }}
          onMouseEnter={e => e.currentTarget.style.color = '#fafafa'}
          onMouseLeave={e => e.currentTarget.style.color = '#71717a'}
        >
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
            <path d="M19 12H5M12 5l-7 7 7 7"/>
          </svg>
          Back
        </button>

        <div style={{ width: '1px', height: '20px', background: 'rgba(255,255,255,0.08)' }} />

        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontSize: '13px', fontWeight: 500, color: '#fafafa', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
            {course.title}
          </div>
        </div>

        {/* Progress */}
        <div style={{ display: 'flex', alignItems: 'center', gap: '10px', flexShrink: 0 }}>
          <div style={{ width: '100px', height: '3px', background: '#1f1f23', borderRadius: '2px', overflow: 'hidden' }}>
            <div style={{ height: '100%', width: `${completionPct}%`, background: '#8b5cf6', borderRadius: '2px', transition: 'width 0.6s ease' }} />
          </div>
          <span style={{ fontSize: '12px', color: '#71717a', whiteSpace: 'nowrap' }}>
            {completedCount}/{totalLessons} &nbsp;&middot;&nbsp; {completionPct}%
          </span>
          {isCompleted && (
            <span className="badge badge-green">Complete</span>
          )}
        </div>

        <button onClick={() => setSidebarOpen(s => !s)} style={{
          background: '#18181b', border: '1px solid rgba(255,255,255,0.08)',
          borderRadius: '8px', color: '#a1a1aa', cursor: 'pointer',
          padding: '5px 12px', fontSize: '12px', fontWeight: 500,
          transition: 'all 0.15s',
        }}>
          {sidebarOpen ? 'Hide' : 'Curriculum'}
        </button>
      </div>

      {/* Body */}
      <div style={{ flex: 1, display: 'flex', overflow: 'hidden' }}>

        {/* Main content */}
        <div style={{ flex: 1, overflow: 'auto', display: 'flex', flexDirection: 'column' }}>

          {/* Video */}
          <div style={{ background: '#000', aspectRatio: '16/9', maxHeight: '52vh', position: 'relative', flexShrink: 0 }}>
            {activeLesson?.videoUrl ? (
              <video ref={videoRef} controls style={{ width: '100%', height: '100%', display: 'block' }}
                src={`http://localhost:5000/${activeLesson.videoUrl}`}
                onEnded={markComplete}
              />
            ) : (
              <div style={{
                width: '100%', height: '100%', minHeight: '240px',
                display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center',
                background: '#111113', color: '#3f3f46',
              }}>
                <svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1" strokeLinecap="round" style={{ marginBottom: '12px' }}>
                  <polygon points="5 3 19 12 5 21 5 3"/>
                </svg>
                <span style={{ fontSize: '13px' }}>No video uploaded for this lesson</span>
              </div>
            )}
          </div>

          {/* Lesson content area */}
          <div style={{ padding: '28px 32px', flex: 1 }}>
            {activeLesson ? (
              <>
                {/* Lesson header */}
                <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: '16px', marginBottom: '20px', flexWrap: 'wrap' }}>
                  <div>
                    <div style={{ fontSize: '11px', color: '#52525b', marginBottom: '6px', fontWeight: 500 }}>
                      {activeModule?.title}
                    </div>
                    <h1 style={{ fontSize: '22px', fontWeight: 700, letterSpacing: '-0.02em' }}>{activeLesson.title}</h1>
                  </div>

                  <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap', flexShrink: 0 }}>
                    {isDone(activeLesson._id) ? (
                      <div style={{
                        display: 'flex', alignItems: 'center', gap: '6px',
                        padding: '8px 16px', borderRadius: '10px',
                        background: 'rgba(16,185,129,0.08)', border: '1px solid rgba(16,185,129,0.2)',
                        fontSize: '13px', fontWeight: 500, color: '#34d399',
                      }}>
                        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round">
                          <polyline points="20 6 9 17 4 12"/>
                        </svg>
                        Completed
                      </div>
                    ) : (
                      <button className="btn btn-accent" onClick={markComplete} disabled={markingDone}>
                        {markingDone ? 'Saving...' : 'Mark as complete'}
                      </button>
                    )}
                    <button className="btn btn-ghost btn-sm" onClick={goNextLesson}>Next lesson</button>
                  </div>
                </div>

                {/* Lesson description */}
                {activeLesson.description && (
                  <div style={{
                    padding: '20px', background: '#111113',
                    border: '1px solid rgba(255,255,255,0.06)',
                    borderRadius: '12px', marginBottom: '20px',
                  }}>
                    <p style={{ fontSize: '14px', color: '#a1a1aa', lineHeight: 1.7 }}>{activeLesson.description}</p>
                  </div>
                )}

                {/* Resources */}
                {activeLesson.resources?.length > 0 && (
                  <div style={{ marginBottom: '20px' }}>
                    <div style={{ fontSize: '12px', fontWeight: 600, color: '#52525b', textTransform: 'uppercase', letterSpacing: '0.06em', marginBottom: '10px' }}>Resources</div>
                    {activeLesson.resources.map((r, i) => (
                      <a key={i} href={r.url} target="_blank" rel="noreferrer" style={{
                        display: 'flex', alignItems: 'center', gap: '8px',
                        padding: '10px 14px', borderRadius: '8px', marginBottom: '6px',
                        background: '#111113', border: '1px solid rgba(255,255,255,0.06)',
                        color: '#a78bfa', fontSize: '13px', fontWeight: 500, textDecoration: 'none',
                        transition: 'border-color 0.15s',
                      }}
                        onMouseEnter={e => e.currentTarget.style.borderColor = 'rgba(139,92,246,0.3)'}
                        onMouseLeave={e => e.currentTarget.style.borderColor = 'rgba(255,255,255,0.06)'}
                      >
                        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
                          <path d="M21.44 11.05l-9.19 9.19a6 6 0 01-8.49-8.49l9.19-9.19a4 4 0 015.66 5.66l-9.2 9.19a2 2 0 01-2.83-2.83l8.49-8.48"/>
                        </svg>
                        {r.name}
                      </a>
                    ))}
                  </div>
                )}

                {/* Quiz (between lessons) */}
                {quizLoading && (
                  <div style={{ display: 'flex', alignItems: 'center', gap: '8px', color: '#52525b', fontSize: '13px', marginBottom: '20px' }}>
                    <div className="spinner" style={{ width: '16px', height: '16px', borderWidth: '1.5px' }} />
                    Loading quiz...
                  </div>
                )}
                {quiz && showQuiz && (
                  <QuizPanel
                    quiz={quiz}
                    onPass={goNextLesson}
                    onSkip={() => { setShowQuiz(false); goNextLesson(); }}
                  />
                )}
                {quiz && !showQuiz && isDone(activeLesson._id) && (
                  <div style={{
                    display: 'flex', alignItems: 'center', justifyContent: 'space-between',
                    padding: '14px 18px', background: '#111113',
                    border: '1px solid rgba(139,92,246,0.15)',
                    borderRadius: '10px', marginBottom: '20px',
                  }}>
                    <div>
                      <div style={{ fontSize: '13px', fontWeight: 600, marginBottom: '2px' }}>Quiz available</div>
                      <div style={{ fontSize: '12px', color: '#71717a' }}>{quiz.title} &nbsp;&middot;&nbsp; {quiz.questions.length} questions</div>
                    </div>
                    <button className="btn btn-ghost btn-sm" onClick={() => setShowQuiz(true)}>Take quiz</button>
                  </div>
                )}

                {/* Certificate banner (when course is 100% done) */}
                {isCompleted && (
                  <CertificateBanner courseId={courseId} courseName={course.title} />
                )}
              </>
            ) : (
              <div style={{ textAlign: 'center', padding: '60px 0', color: '#52525b' }}>
                Select a lesson from the sidebar to begin
              </div>
            )}
          </div>
        </div>

        {/* Sidebar */}
        {sidebarOpen && (
          <div style={{
            width: '300px', flexShrink: 0,
            background: '#0d0d0f',
            borderLeft: '1px solid rgba(255,255,255,0.06)',
            overflow: 'auto',
            display: 'flex', flexDirection: 'column',
          }}>
            {/* Sidebar header */}
            <div style={{ padding: '16px 18px', borderBottom: '1px solid rgba(255,255,255,0.06)', flexShrink: 0 }}>
              <div style={{ fontSize: '11px', fontWeight: 600, color: '#52525b', textTransform: 'uppercase', letterSpacing: '0.06em', marginBottom: '8px' }}>
                Course content
              </div>
              <div style={{ height: '3px', background: '#1f1f23', borderRadius: '2px', overflow: 'hidden' }}>
                <div style={{ height: '100%', width: `${completionPct}%`, background: '#8b5cf6', borderRadius: '2px', transition: 'width 0.6s ease' }} />
              </div>
              <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: '6px' }}>
                <span style={{ fontSize: '11px', color: '#3f3f46' }}>{completedCount} of {totalLessons} complete</span>
                <span style={{ fontSize: '11px', color: '#8b5cf6', fontWeight: 600 }}>{completionPct}%</span>
              </div>
            </div>

            {/* Modules */}
            {course.modules?.map((mod, mi) => {
              const modDone = mod.lessons.filter(l => isDone(l._id)).length;
              const isOpen = openModules[mod._id];
              return (
                <div key={mod._id} style={{ borderBottom: '1px solid rgba(255,255,255,0.04)' }}>
                  <button onClick={() => toggleModule(mod._id)} style={{
                    width: '100%', padding: '12px 18px', background: 'none', border: 'none',
                    display: 'flex', alignItems: 'flex-start', gap: '10px',
                    cursor: 'pointer', textAlign: 'left',
                    transition: 'background 0.15s',
                  }}
                    onMouseEnter={e => e.currentTarget.style.background = 'rgba(255,255,255,0.02)'}
                    onMouseLeave={e => e.currentTarget.style.background = 'none'}
                  >
                    <svg style={{ flexShrink: 0, marginTop: '2px', transition: 'transform 0.2s', transform: isOpen ? 'rotate(90deg)' : 'none' }}
                      width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="#52525b" strokeWidth="2" strokeLinecap="round">
                      <polyline points="9 18 15 12 9 6"/>
                    </svg>
                    <div style={{ flex: 1 }}>
                      <div style={{ fontSize: '13px', fontWeight: 600, color: '#d4d4d8', marginBottom: '3px', lineHeight: 1.4 }}>
                        {mi + 1}. {mod.title}
                      </div>
                      <div style={{ fontSize: '11px', color: '#52525b' }}>
                        {modDone}/{mod.lessons.length} lessons
                      </div>
                    </div>
                  </button>

                  {isOpen && mod.lessons.map((lesson, li) => {
                    const done = isDone(lesson._id);
                    const isActive = activeLesson?._id === lesson._id;
                    return (
                      <button key={lesson._id} onClick={() => selectLesson(mod, lesson)} style={{
                        width: '100%', padding: '10px 18px 10px 36px',
                        background: isActive ? 'rgba(139,92,246,0.1)' : 'none',
                        border: 'none',
                        borderLeft: `2px solid ${isActive ? '#8b5cf6' : 'transparent'}`,
                        display: 'flex', alignItems: 'center', gap: '10px',
                        cursor: 'pointer', textAlign: 'left',
                        transition: 'all 0.15s',
                      }}
                        onMouseEnter={e => { if (!isActive) e.currentTarget.style.background = 'rgba(255,255,255,0.03)'; }}
                        onMouseLeave={e => { if (!isActive) e.currentTarget.style.background = 'none'; }}
                      >
                        {/* Status icon */}
                        <div style={{
                          width: '18px', height: '18px', borderRadius: '50%', flexShrink: 0,
                          background: done ? '#10b981' : '#1f1f23',
                          border: `1px solid ${done ? '#10b981' : 'rgba(255,255,255,0.08)'}`,
                          display: 'flex', alignItems: 'center', justifyContent: 'center',
                        }}>
                          {done && (
                            <svg width="9" height="9" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="3" strokeLinecap="round">
                              <polyline points="20 6 9 17 4 12"/>
                            </svg>
                          )}
                          {!done && lesson.videoUrl && (
                            <svg width="7" height="7" viewBox="0 0 24 24" fill="#52525b">
                              <polygon points="5 3 19 12 5 21 5 3"/>
                            </svg>
                          )}
                        </div>
                        <div style={{ flex: 1, minWidth: 0 }}>
                          <div style={{
                            fontSize: '12px', lineHeight: 1.4,
                            color: isActive ? '#fafafa' : done ? '#71717a' : '#a1a1aa',
                            fontWeight: isActive ? 500 : 400,
                            whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis',
                          }}>{lesson.title}</div>
                          {lesson.duration > 0 && (
                            <div style={{ fontSize: '10px', color: '#3f3f46', marginTop: '2px' }}>
                              {Math.floor(lesson.duration / 60)}:{String(lesson.duration % 60).padStart(2, '0')}
                            </div>
                          )}
                        </div>
                        {lesson.isFree && !done && (
                          <span style={{ fontSize: '9px', color: '#10b981', border: '1px solid rgba(16,185,129,0.3)', borderRadius: '4px', padding: '1px 5px', flexShrink: 0 }}>Free</span>
                        )}
                      </button>
                    );
                  })}
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}
